func completeEnvs(
    cmd *cobra.Command,
    args []string,
    toComplete string,
) ([]string, cobra.ShellCompDirective) {
    var matches []string
    for _, env := range envs {
        if strings.HasPrefix(env, toComplete) {
            matches = append(matches, env)
        }
    }
    return matches,
        cobra.ShellCompDirectiveNoFileComp
}

deploy := &cobra.Command{
